ALTER TABLE public.products ADD COLUMN IF NOT EXISTS supplier_availability text NOT NULL DEFAULT 'unknown', ADD COLUMN IF NOT EXISTS supplier_stock_checked_at timestamptz, ADD COLUMN IF NOT EXISTS supplier_confirmed_quantity integer NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS products_amazon_stock_check_idx ON public.products (supplier_stock_checked_at ASC NULLS FIRST, id) WHERE supplier='amazon';
CREATE OR REPLACE FUNCTION public.protect_supplier_availability() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user <> 'service_role' AND coalesce(auth.role(),'') <> 'service_role' THEN IF TG_OP='INSERT' THEN NEW.supplier_availability:='unknown'; NEW.supplier_stock_checked_at:=NULL; NEW.supplier_confirmed_quantity:=0; ELSIF NEW.supplier_availability IS DISTINCT FROM OLD.supplier_availability OR NEW.supplier_stock_checked_at IS DISTINCT FROM OLD.supplier_stock_checked_at OR NEW.supplier_confirmed_quantity IS DISTINCT FROM OLD.supplier_confirmed_quantity THEN RAISE EXCEPTION 'Disponibilidade deve ser confirmada pelo servidor.'; END IF; END IF; IF NEW.supplier='amazon' THEN IF NEW.supplier_availability <> 'available' OR NEW.supplier_confirmed_quantity < 1 OR jsonb_array_length(coalesce(NEW.variations,'[]'::jsonb))>0 THEN NEW.stock:=0; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_supplier_availability BEFORE INSERT OR UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.protect_supplier_availability();
CREATE OR REPLACE FUNCTION public.guard_amazon_order_stock() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.products; BEGIN SELECT * INTO p FROM public.products WHERE id=NEW.product_id; IF p.supplier='amazon' AND (p.supplier_availability <> 'available' OR p.supplier_stock_checked_at IS NULL OR p.supplier_stock_checked_at < now()-interval '5 minutes' OR p.supplier_confirmed_quantity < NEW.quantity OR jsonb_array_length(coalesce(p.variations,'[]'::jsonb))>0) THEN RAISE EXCEPTION 'Produto indisponível ou estoque não confirmado. Atualize o carrinho.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_amazon_order_stock BEFORE INSERT ON public.order_items FOR EACH ROW EXECUTE FUNCTION public.guard_amazon_order_stock();
REVOKE ALL ON FUNCTION public.protect_supplier_availability() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_amazon_order_stock() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.protect_supplier_availability(),public.guard_amazon_order_stock() TO service_role;
UPDATE public.products SET supplier_availability='unknown',supplier_confirmed_quantity=0,stock=0 WHERE supplier='amazon';